const companies = $input.all();
const requests = [];

for (const company of companies) {
  const url = `https://api.crunchbase.com/api/v4/entities/organizations/${company.json.name.toLowerCase().replace(/\s+/g, '-')}`;
  requests.push({
    company_id: company.json.id,
    url: url,
    headers: { 'X-cb-user-key': '{{$env.CRUNCHBASE_API_KEY}}' }
  });
}

return requests.map(r => ({ json: r }));

const response = $input.first().json;
const companyId = $node['Prepare Requests'].json.company_id;
const fundingRounds = [];

try {
  const properties = response.properties || {};
  const cards = response.cards || {};

  if (cards.funding_rounds && cards.funding_rounds.length > 0) {
    for (const round of cards.funding_rounds) {
      const roundProps = round.properties || {};

      fundingRounds.push({
        company_id: companyId,
        round_type: roundProps.funding_type || 'Unknown',
        amount_usd: roundProps.money_raised ? roundProps.money_raised.value_usd : null,
        announcement_date: roundProps.announced_on || null,
        lead_investors: roundProps.lead_investors ? roundProps.lead_investors.map(i => i.name) : [],
        participating_investors: roundProps.investors ? roundProps.investors.map(i => i.name) : [],
        investor_count: roundProps.num_investors || 0,
        source: 'Crunchbase',
        raw_data: JSON.stringify(round)
      });
    }
  }
} catch (error) {
  console.error('Parse error:', error.message);
}

return fundingRounds.map(f => ({ json: f }));

const rounds = $input.all();
const alerts = [];

for (const round of rounds) {
  const data = round.json;

  // Alert on rounds > $10M
  if (data.amount_usd && data.amount_usd > 10000000) {
    alerts.push({
      company_id: data.company_id,
      alert_type: 'funding_round',
      priority: data.amount_usd > 50000000 ? 'high' : 'medium',
      title: `${data.round_type}: $${(data.amount_usd/1000000).toFixed(1)}M Raised`,
      description: `Lead investors: ${data.lead_investors.join(', ')}`,
      data: JSON.stringify(data),
      created_at: new Date().toISOString()
    });
  }
}

return alerts.map(a => ({ json: a }));
